public static int membershipLevel(int membershipPoints) {
    if (membershipPoints >= 6) {
        return 4;
    }
    if (membershipPoints >= 4) {
        return 3;
    }
    if (membershipPoints >= 2) {
        return 2;
    }
    return 1;
