    int uncapped = effectiveMembershipLevel(owner);
    String householdId = Owner.householdId(owner.getLastName(), owner.getPostcode());
    if (householdId == null) {
        return uncapped;
    }
    Integer maxHouseholdLevel = ownerRepository.findAll().stream()
        .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
        .filter(existing -> !existing.isDeleted())
        .filter(existing -> householdId.equals(
            Owner.householdId(existing.getLastName(), existing.getPostcode())))
        .map(this::effectiveMembershipLevel)
        .max(Integer::compareTo)
        .orElse(null);
    if (maxHouseholdLevel == null) {
        return uncapped;
    }
    return Math.min(uncapped, maxHouseholdLevel + 1);
}

/**
 * Resolve an owner's effective {@code membershipLevel}: the capped value stored on the owner when
 * present (see {@link Owner#getMembershipLevel()}), otherwise the level recomputed from the
 * owner's membership points (see {@link Owner#membershipLevel(int)}). This shared accessor lets
 * the household-ceiling computation compare against each household member's final level whether or
 * not that member carries a stored value.
 */
private int effectiveMembershipLevel(Owner owner) {
    Integer stored = owner.getMembershipLevel();
    if (stored != null) {
        return stored;
    }
    return Owner.membershipLevel(Owner.membershipPoints(
        owner.getNamesakeCount(), owner.getEmail(), owner.getHouseholdCount(),
        owner.getRegistrationDate()));
}

